import * as React from "react";
import { createRoot } from "react-dom/client";
import App from "./components/App";
import { FluentProvider, webLightTheme } from "@fluentui/react-components";
import { HashRouter } from "react-router-dom";
import RouterApp from "./Router/Routes";
import { createTheme, ThemeProvider } from "@mui/material";
import { SnackbarProvider } from "notistack";

/* global document, Office, module, require, HTMLElement */

// const title = "Contoso Task Pane Add-in";
const theme = createTheme({
    palette: { mode: 'dark', primary: { main: '#8f94fb' }, secondary: { main: '#764ba2' } },
    typography: { fontFamily: '"Inter", "Roboto", "Helvetica", "Arial", sans-serif', button: { textTransform: 'none' } },
  });
const rootElement: HTMLElement | null = document.getElementById("container");
const root = rootElement ? createRoot(rootElement) : undefined;

/* Render application after Office initializes */
Office.onReady(() => {
  root?.render(
<ThemeProvider theme={theme}>
  <SnackbarProvider
  maxSnack={3}
  anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
  autoHideDuration={3000}
>
       <HashRouter>
   <RouterApp/>
       </HashRouter>
       </SnackbarProvider>
    </ThemeProvider>
  );
});

if ((module as any).hot) {
  (module as any).hot.accept("./Router/Routes", () => {
    const NextApp = require("./Router/Routes").default;
    root?.render(NextApp);
  });
}
