import { supabase } from "./supabaseClient";

interface StoreClauseProps {
  clause_text: string;
  source_type: 'playbook' | 'chat' | 'manual' | 'fallback' | 'restored'; // Add 'restored'
  reason?: string;
  rule_id?: string;
  user_id: string;
  anchor_tag_id?: string;
}

export const StoreClause = async ({ clause_text, source_type, reason, rule_id, user_id, anchor_tag_id }: StoreClauseProps) => {
  // Step 1: User authentication check
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user || user.id !== user_id) {
    console.error('Authentication failed for user_id:', user_id);
    return { data: null, error: new Error('User not authenticated or invalid user_id.') };
  }

  // Step 2: Validate rule_id based on source_type
  if (source_type === 'playbook' && !rule_id) {
    console.error('No rule_id provided for clause with source_type "playbook":', clause_text);
    return { data: null, error: new Error('rule_id is required for playbook source type.') };
  }

  // Step 3: Prepare payload for Supabase
  const payload = {
    clause_text,
    source_type,
    reason: reason || null,
    rule_id: rule_id || null,
    user_id,
    applied_at: new Date().toISOString(),
    anchor_tag_id: anchor_tag_id || null, // Use provided anchor_tag_id or null
    version_id: null,
    doc_id: null,
  };

  console.log('Saving clause to Supabase with payload:', payload);

  // Step 4: Insert into applied_clause_instances and return clause_instance_id
  const { data, error } = await supabase
    .from('applied_clause_instances')
    .insert(payload)
    .select('clause_instance_id')
    .single();

  if (error) {
    console.error('Supabase insert error for clause with rule_id:', rule_id || 'null', 'Error:', error.message);
    return { data: null, error: new Error(`Failed to save clause: ${error.message}`) };
  }
  console.log('Clause saved to Supabase with clause_instance_id:', data.clause_instance_id, 'and anchor_tag_id:', anchor_tag_id || 'null');

  return { data: { clauseInstanceId: data.clause_instance_id }, error: null };
};

export const UpdateClauseAnchor = async (clauseInstanceId: string, anchorTagId: string) => {
  console.log(`Updating anchor_tag_id for clauseInstanceId: ${clauseInstanceId} with anchorTagId: ${anchorTagId}`);
  const { data, error } = await supabase
    .from('applied_clause_instances')
    .update({ anchor_tag_id: anchorTagId })
    .eq('clause_instance_id', clauseInstanceId);

  if (error) {
    console.error('Failed to update anchor_tag_id for clauseInstanceId:', clauseInstanceId, 'Error:', error.message);
    return { data: null, error: new Error(`Failed to update anchor: ${error.message}`) };
  }
  console.log('Anchor tag ID updated successfully for clauseInstanceId:', clauseInstanceId, 'to anchorTagId:', anchorTagId);
  return { data, error: null };
};