import React from 'react';
import {
  Box,
  Button,
  Typography,
  Container,
  Divider,
} from '@mui/material';
import ChatBubbleOutlineIcon from '@mui/icons-material/ChatBubbleOutline'; // Chat Icon
import EditIcon from '@mui/icons-material/Edit'; // Rewrite Icon
import InsertChartIcon from '@mui/icons-material/InsertChart'; // Benchmark Icon
import LightbulbIcon from '@mui/icons-material/Lightbulb'; // Generate Icon
import SearchIcon from '@mui/icons-material/Search'; // Review with AI Icon
import BookIcon from '@mui/icons-material/Book'; // Review with Playbook Icon
import AccountCircleIcon from '@mui/icons-material/AccountCircle'; // User Icon


interface HomeTabProps {
  setActiveTab: (tab: number) => void;
  setMode?: (mode: string) => void;
}

const HomeTab: React.FC<HomeTabProps> = ({ setActiveTab, setMode }) => {
  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column', // Changed to column
        alignItems: 'center',
        justifyContent: 'flex-start', // Align items at the top
        py: 4,
      }}
    >
      <Container maxWidth="sm">
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 2, // Reduced gap for tighter spacing
            alignItems: 'stretch', // Stretch items to fill container width
            textAlign: 'left', // Align text to the left
          }}
        >
          {/* Assistant Tools */}
          <Box>
            <Typography variant="h6" fontWeight="bold" gutterBottom>
              Assistant Tools
            </Typography>
            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1 }}>
              {[
                { label: 'Chat', mode: 'suggestion', icon: <ChatBubbleOutlineIcon /> },
                { label: 'Rewrite', mode: 'edit', icon: <EditIcon /> },
                { label: 'Generate', mode: 'draft', icon: <LightbulbIcon /> },
                { label: 'Benchmark', mode: 'benchmark', icon: <InsertChartIcon /> },
              ].map((tool) => (
                <Button
                  key={tool.mode}
                  variant="outlined" // Changed to outlined
                  startIcon={tool.icon}
                  onClick={() => {
                    setActiveTab(1);
                    if (setMode) setMode(tool.mode);
                  }}
                  aria-label={tool.label}
                  sx={{
                    fontWeight: 'normal', // Removed bold
                    textTransform: 'none',
                    fontSize: '0.9rem',
                    color: 'inherit', // Inherit color from parent
                    py: 1.5, // Adjusted padding
                    justifyContent: 'flex-start', // Align text to the left
                    borderColor: 'rgba(0, 0, 0, 0.23)', // subtle border
                    borderRadius: '8px',
                    boxShadow:'0px 0px 1px 1px white',
                  }}
                >
                  {tool.label}
                </Button>
              ))}
            </Box>
          </Box>

          <Divider
            sx={{
              width: '100%',
              borderColor: 'rgba(0,0,0,0.12)',
              my: 2,
            }}
          />

          {/* Document Review */}
          <Box>
            <Typography variant="h6" fontWeight="bold" gutterBottom>
              Document Review
            </Typography>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {[
                { label: 'Review with AI', mode: 'ai-review',  icon: <SearchIcon /> },
                { label: 'Review with Playbook', mode: 'playbook', icon: <BookIcon /> },
              ].map((tool) => (
                <Button
                  key={tool.mode}
                  variant="outlined" // Changed to outlined
                  startIcon={tool.icon}

                  onClick={() => {
                    if (tool.mode === 'ai-review') {
                      setActiveTab(2);
                      if (setMode) setMode('ai-review');
                    } else {
                      setActiveTab(2);
                      if (setMode) setMode('playbook');
                    }
                  }}
                  aria-label={tool.label}
                  sx={{
                    fontWeight: 'normal', // Removed bold
                    textTransform: 'none',
                    fontSize: '0.9rem',
                    color: 'inherit', // Inherit color
                    py: 1.5, // Adjusted padding
                    justifyContent: 'flex-start', // Align text to the left
                    borderColor: 'rgba(0, 0, 0, 0.23)', // subtle border
                    borderRadius: '8px',
                    boxShadow:'0px 0px 1px 1px white',
                    marginBottom:'3px'
                  }}
                >
                  {tool.label}
                </Button>
              ))}
            </Box>
          </Box>
        </Box>
      </Container>
    </Box>
  );
};

export default HomeTab;