import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  List,
  ListItem,
  ListItemText,
  Snackbar,
  Typography,
  IconButton,
  Tooltip,
  DialogContentText,
} from "@mui/material";
import { ContentCopy as CopyIcon, History as HistoryIcon } from "@mui/icons-material";
import React, { useEffect, useState, useRef } from "react";
import { StoreClause, UpdateClauseAnchor } from "../Services/StoreClause";
import { supabase } from "../Services/supabaseClient";

interface ClauseHistoryViewerProps {
  open: boolean;
  onClose: () => void;
  clauseInstanceId: string;
  anchorTagId?: string;
  onClauseRestored?: (clauseInstanceId: string, clauseText: string) => void;
}

const ClauseHistoryViewer = ({
  open,
  onClose,
  clauseInstanceId,
  anchorTagId,
  onClauseRestored,
}: ClauseHistoryViewerProps) => {
  const [history, setHistory] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notification, setNotification] = useState<{
    open: boolean;
    message: string;
    severity: "success" | "error";
  } | null>(null);
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [selectedClauseText, setSelectedClauseText] = useState<string | null>(null);
  const [restoreLoading, setRestoreLoading] = useState(false);
  const dialogContentRef = useRef<HTMLDivElement>(null); // For focus management

  // Fetch history with retry and fallback logic
  const fetchHistory = async (retries = 3, delayMs = 1500) => {
    if (!clauseInstanceId && !anchorTagId) {
      console.warn("No clauseInstanceId or anchorTagId provided for fetchHistory");
      return;
    }
    setIsLoading(true);
    setError(null);

    const user = await supabase.auth.getUser();
    const userId = user.data.user?.id || "";

    let success = false;
    for (let attempt = 1; attempt <= retries; attempt++) {
      try {
        let query = supabase
          .from("applied_clause_instances")
          .select("clause_instance_id, clause_text, source_type, reason, applied_at, user_id, rule_id, anchor_tag_id")
          .order("applied_at", { ascending: false });

        if (anchorTagId) {
          query = query.eq("anchor_tag_id", anchorTagId); // Prioritize anchor_tag_id
        } else {
          query = query.eq("clause_instance_id", clauseInstanceId);
        }

        let { data, error } = await query;
        if (error) throw error;

        // Fallback: If no data with anchor_tag_id, try user_id + recent applied_at
        if ((!data || data.length === 0) && userId && attempt === 1) {
          console.log(`Attempt ${attempt}: No data for anchorTagId: ${anchorTagId}, falling back to user_id`);
          query = supabase
            .from("applied_clause_instances")
            .select("clause_instance_id, clause_text, source_type, reason, applied_at, user_id, rule_id, anchor_tag_id")
            .eq("user_id", userId)
            .gte("applied_at", new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()) // Last 24 hours
            .order("applied_at", { ascending: false });
          ({ data, error } = await query);
          if (error) throw error;
        }

        console.log(`Fetch history attempt ${attempt}:`, {
          anchorTagId,
          clauseInstanceId,
          userId,
          result: data,
        });
        setHistory(data || []);
        success = true;
        break; // Success, exit loop
      } catch (err) {
        console.error(`Fetch history attempt ${attempt} failed:`, err);
        if (attempt === retries) {
          setError("Failed to load clause history after retries.");
          setNotification({
            open: true,
            message: "Failed to load clause history. Please try again.",
            severity: "error",
          });
        }
        await new Promise(resolve => setTimeout(resolve, delayMs)); // Wait before retry
      }
    }

    setIsLoading(false); // Always stop loading
  };

  useEffect(() => {
    if (open) {
      fetchHistory();
    }
  }, [open, clauseInstanceId, anchorTagId]);

  const handleViewInDocument = async () => {
    if (!anchorTagId) return;
    try {
      await Word.run(async (context) => {
        const contentControls = context.document.contentControls.getByTag(anchorTagId);
        contentControls.load("items");
        await context.sync();
        if (contentControls.items.length > 0) {
          contentControls.items[0].select("Select");
          contentControls.items[0].font.highlightColor = "#FFFF00";
          await context.sync();
          setTimeout(async () => {
            contentControls.items[0].font.highlightColor = null;
            await context.sync();
          }, 2000);
        }
      });
      setNotification({
        open: true,
        message: "Navigated to clause in document.",
        severity: "success",
      });
    } catch (error) {
      console.error("View in document error:", error);
      setNotification({
        open: true,
        message: "Failed to navigate to clause.",
        severity: "error",
      });
    }
  };

  const handleCopy = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setNotification({
        open: true,
        message: "Copied to clipboard!",
        severity: "success",
      });
    } catch (error) {
      console.error("Copy error:", error);
      setNotification({
        open: true,
        message: "Failed to copy to clipboard.",
        severity: "error",
      });
    }
  };

  const handleRestoreConfirm = (clauseText: string) => {
    setSelectedClauseText(clauseText);
    setConfirmDialogOpen(true);
    // Move focus to dialog content to avoid ARIA issue
    setTimeout(() => {
      dialogContentRef.current?.focus();
    }, 0);
  };

  const handleRestore = async () => {
    if (!selectedClauseText) return;
    setRestoreLoading(true);
    setConfirmDialogOpen(false); // Close dialog early to avoid ARIA focus issue
    try {
      await Word.run(async (context) => {
        const range = context.document.getSelection();
        const insertedRange = range.insertText(selectedClauseText, Word.InsertLocation.replace);

        // Apply Chat pipeline formatting (redline styling)
        insertedRange.font.bold = true;
        insertedRange.font.color = "#2E7D32"; // Green
        insertedRange.font.underline = Word.UnderlineType.single;
        insertedRange.load("text"); // Load text for logging
        await context.sync();
        console.log("Inserted range formatted:", insertedRange.text);

        // Apply temporary highlight
        insertedRange.font.highlightColor = "#FFFF00"; // Yellow highlight
        await context.sync();
        console.log("Applied yellow highlight to inserted range");

        // Find original version ID for metadata
        const originalVersionId = history.find(h => h.clause_text === selectedClauseText)?.clause_instance_id || 'unknown';

        const { data, error } = await StoreClause({
          clause_text: selectedClauseText,
          source_type: "restored", // Fallback: "chat" if backend not updated
          // source_type: "chat",
          reason: `Restored from version history (Original ID: ${originalVersionId})`,
          user_id: (await supabase.auth.getUser()).data.user?.id || "",
          rule_id: null,
          anchor_tag_id: anchorTagId, // Explicitly pass anchor_tag_id
        });

        console.log("StoreClause response:", data, error); // Debug log

        if (error) {
          console.error("Failed to save restored clause:", error.message);
          setNotification({
            open: true,
            message: `Failed to save restored clause: ${error.message}`,
            severity: "error",
          });
          return;
        }

        if (data?.clauseInstanceId && insertedRange) {
          const contentControlTag = `clause_${data.clauseInstanceId}`;
          const contentControl = insertedRange.insertContentControl();
          contentControl.tag = contentControlTag;
          contentControl.title = `Clause ${data.clauseInstanceId}`;
          contentControl.cannotEdit = true;
          contentControl.appearance = Word.ContentControlAppearance.hidden;
          await context.sync();
          console.log("Content control created:", { tag: contentControlTag, title: contentControl.title });

          await UpdateClauseAnchor(data.clauseInstanceId, contentControlTag);
          console.log("Updated anchor:", contentControlTag);

          // Ensure scroll to inserted text
          insertedRange.select("Select");
          await context.sync();
          console.log("Scrolled to inserted range");

          // Remove highlight after 2s
          setTimeout(async () => {
            await Word.run(async (context) => {
              insertedRange.load("text");
              insertedRange.font.highlightColor = null;
              await context.sync();
              console.log("Removed yellow highlight");
            });
          }, 2000);

          // Wait 1000ms before auto-refresh with retries
          await new Promise(resolve => setTimeout(resolve, 1000));
          await fetchHistory(); // Auto-refresh with retries

          setNotification({
            open: true,
            message: `Clause restored successfully! ID: ${data.clauseInstanceId}`,
            severity: "success",
          });

          if (onClauseRestored) {
            onClauseRestored(data.clauseInstanceId, selectedClauseText);
          }
        }
      });
    } catch (error) {
      console.error("Restore error:", error);
      setNotification({
        open: true,
        message: `Failed to restore clause: ${
          error instanceof Error ? error.message : "Unknown error"
        }`,
        severity: "error",
      });
    } finally {
      setRestoreLoading(false);
      setSelectedClauseText(null);
    }
  };

  const handleCloseNotification = () => {
    setNotification(null);
  };

  const handleCloseConfirmDialog = () => {
    setConfirmDialogOpen(false);
    setSelectedClauseText(null);
  };

  return (
    <>
      <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ background: "linear-gradient(135deg, #42475A, #303442)", color: "white" }}>
          Clause History
        </DialogTitle>
        <DialogContent sx={{ background: "#2A2D3A", color: "white" }} ref={dialogContentRef} tabIndex={-1}>
          {isLoading && (
            <CircularProgress
              size={24}
              sx={{ color: "#3DDC84", display: "block", mx: "auto" }}
            />
          )}
          {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
          {history.length === 0 && !isLoading && !error && (
            <Typography sx={{ color: "rgba(255,255,255,0.7)" }}>
              No history available for this clause.
            </Typography>
          )}
          <List>
            {history.map((item, index) => (
              <ListItem
                key={item.clause_instance_id || index}
                sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}
              >
                <ListItemText
                  primary={
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                      <Typography
                        variant="body2"
                        sx={{ color: "white", flex: 1 }}
                      >
                        {item.clause_text}
                      </Typography>
                      <Tooltip title="Copy to Clipboard">
                        <IconButton
                          onClick={() => handleCopy(item.clause_text)}
                          sx={{
                            color: "rgba(255,255,255,0.8)",
                            "&:hover": { color: "#3DDC84", transform: "scale(1.1)" },
                            transition: "all 0.2s",
                          }}
                        >
                          <CopyIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="Restore this Clause">
                        <IconButton
                          onClick={() => handleRestoreConfirm(item.clause_text)}
                          disabled={restoreLoading}
                          sx={{
                            color: "rgba(255,255,255,0.8)",
                            "&:hover": { color: "#3DDC84", transform: "scale(1.1)" },
                            transition: "all 0.2s",
                          }}
                        >
                          <HistoryIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </Box>
                  }
                  secondary={
                    <Box>
                      <Typography
                        variant="caption"
                        sx={{ color: "rgba(255,255,255,0.6)" }}
                      >
                        {`Source: ${item.source_type} | Applied: ${new Date(
                          item.applied_at
                        ).toLocaleString()}`}
                      </Typography>
                      <Typography
                        variant="caption"
                        sx={{
                          color: "rgba(255,255,255,0.6)",
                          display: "block",
                        }}
                      >
                        {`Reason: ${item.reason || "N/A"}`}
                      </Typography>
                    </Box>
                  }
                />
              </ListItem>
            ))}
          </List>
          {anchorTagId && (
            <Button
              variant="contained"
              onClick={handleViewInDocument}
              sx={{
                mt: 2,
                background: "linear-gradient(45deg, #7B1FA2, #1976D2)",
                "&:hover": {
                  background: "linear-gradient(45deg, #9C27B0, #2196F3)",
                },
              }}
            >
              View in Document
            </Button>
          )}
        </DialogContent>
        <DialogActions sx={{ background: "#2A2D3A", p: 2 }}>
          <Button
            variant="contained"
            onClick={onClose}
            disabled={restoreLoading}
            sx={{
              background: "linear-gradient(45deg, #f44336, #d32f2f)",
              "&:hover": {
                background: "linear-gradient(45deg, #ef5350, #e53935)",
              },
              textTransform: "none",
              borderRadius: "8px",
              padding: "6px 16px",
              fontWeight: "medium",
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
      <Dialog open={confirmDialogOpen} onClose={handleCloseConfirmDialog}>
        <DialogTitle>Confirm Restore</DialogTitle>
        <DialogContent tabIndex={-1} ref={dialogContentRef}>
          <DialogContentText>
            Are you sure you want to restore this clause? It will replace the
            current selection in the document.
          </DialogContentText>
          {selectedClauseText && (
            <Typography variant="body2" sx={{ mt: 1, fontStyle: "italic", color: "rgba(255,255,255,0.8)" }}>
              Preview: "{selectedClauseText.substring(0, 50)}..."
            </Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseConfirmDialog} disabled={restoreLoading}>
            Cancel
          </Button>
          <Button 
            onClick={handleRestore} 
            variant="contained"
            disabled={restoreLoading}
            sx={{
              background: "linear-gradient(45deg, #7B1FA2, #1976D2)",
              "&:hover": { background: "linear-gradient(45deg, #9C27B0, #2196F3)" },
            }}
          >
            {restoreLoading ? <CircularProgress size={20} color="inherit" /> : "Restore"}
          </Button>
        </DialogActions>
      </Dialog>
      {notification && (
        <Snackbar
          open={notification.open}
          autoHideDuration={notification.severity === "success" ? 2000 : 3000}
          onClose={handleCloseNotification}
          anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
        >
          <Alert
            onClose={handleCloseNotification}
            severity={notification.severity}
            sx={{ width: "100%" }}
          >
            {notification.message}
          </Alert>
        </Snackbar>
      )}
    </>
  );
};

export default ClauseHistoryViewer;