import React, { useState } from "react";
import {
  Box,
  Typography,
  TextField,
  CssBaseline,
  ThemeProvider,
  CircularProgress,
} from "@mui/material";
import { useSnackbar } from "notistack";
import { useNavigate } from "react-router-dom";
import {
  appTheme,
  GlassmorphicCard,
  GradientButton,
  PRIMARY_GRADIENT,
} from "../Utils/theme";
import { supabase } from "../Services/supabaseClient";

const LoginPage = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isSignUp, setIsSignUp] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const { enqueueSnackbar } = useSnackbar();
  const navigate = useNavigate();

  const handleSubmit = async () => {
    if (!email || !password) {
      enqueueSnackbar("Email and password are required.", { variant: "warning" });
      return;
    }

    setIsLoading(true);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({ email, password });
        if (error) {
          enqueueSnackbar(error.message, { variant: "error" });
        } else {
          enqueueSnackbar("Sign-up successful! Check your email to confirm.", { variant: "success" });
          navigate("/Home");
        }
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) {
          enqueueSnackbar(error.message, { variant: "error" });
        } else {
          enqueueSnackbar("Login successful!", { variant: "success" });
          navigate("/Home");
        }
      }
    } catch (e) {
      enqueueSnackbar("Unexpected error. Please try again.", { variant: "error" });
    } finally {
      setIsLoading(false);
    }
  };


  return (
    <ThemeProvider theme={appTheme}>
      <CssBaseline />
      <Box
        sx={{
          background: PRIMARY_GRADIENT,
          minHeight: "100vh",
          color: "#fff",
          alignItems: "center",
          justifyContent: "center",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <Box
          sx={{
            flexGrow: 1,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <GlassmorphicCard
            sx={{
              width: "100%",
              p: 3,
              textAlign: "center",
              maxWidth: 400,
              margin: "10px",
              height: "480px",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "space-around",
            }}
          >
            <Typography variant="h6" sx={{ fontWeight: "bold", color: "#fff" }}>
              {isSignUp ? "Create Account" : "Welcome Back"}
            </Typography>


            <Typography variant="body1" sx={{  color: "#fff" }}>
              {isSignUp ? "Create Account" : "Please login to continue using add-in"}
            </Typography>
            <Box>
              <TextField
                label="Email"
                variant="standard"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                fullWidth
                sx={{
                  label: { color: "rgba(255,255,255,0.7)" },
                  input: { color: "white" },
                  "& .MuiInput-underline:before": { borderBottomColor: "rgba(255,255,255,0.3)" },
                  "& .MuiInput-underline:hover:before": { borderBottomColor: "rgba(255,255,255,0.5)" },
                  "& .MuiInput-underline:after": { borderBottomColor: "primary.main" },
                  mb: 2,
                }}
              />

              <TextField
                label="Password"
                type="password"
                variant="standard"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                fullWidth
                sx={{
                  label: { color: "rgba(255,255,255,0.7)" },
                  input: { color: "white" },
                  "& .MuiInput-underline:before": { borderBottomColor: "rgba(255,255,255,0.3)" },
                  "& .MuiInput-underline:hover:before": { borderBottomColor: "rgba(255,255,255,0.5)" },
                  "& .MuiInput-underline:after": { borderBottomColor: "primary.main" },
                  mb: 2,
                }}
              />
            </Box>
            <GradientButton
              fullWidth
              sx={{ textTransform: "none", fontWeight: "bold", mt: 1 }}
              onClick={handleSubmit}
              disabled={isLoading}
            >
              {isLoading ? <CircularProgress size={22} color="inherit" /> : isSignUp ? "Sign Up" : "Login"}
              
            </GradientButton>
<i>v5.2</i>
            {/* <Typography variant="body2" sx={{ mt: 2 }}>
              {isSignUp ? "Already have an account?" : "Don't have an account?"}
              <button
                onClick={() => setIsSignUp(!isSignUp)}
                style={{
                  background: "none",
                  border: "none",
                  color: appTheme.palette.primary.main,
                  fontWeight: "bold",
                  marginLeft: "5px",
                  cursor: "pointer",
                }}
              >
                {isSignUp ? "Login" : "Sign Up"}
              </button>
            </Typography> */}

             
          </GlassmorphicCard>
        </Box>
      </Box>
    </ThemeProvider>
  );
};

export default LoginPage;
