// PlaybookTab.tsx (No changes needed as per the plan, but including the original for completeness)
import { useState, useEffect } from "react";
import {
  Typography,
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Alert,
  Tabs,
  Tab,
  Switch,
} from "@mui/material";
import {
  ExpandMore,
  FileCopy as FileCopyIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
  Send as SendIcon,
} from "@mui/icons-material";
import { useSnackbar } from "notistack";
import { debounce } from 'lodash';
import { GlassmorphicCard, PulsingButton } from "../Utils/styles";
import { Playbook, Rule } from "../Utils/types";
import { createPlaybook, updatePlaybook, deletePlaybook } from "../Services/Playbook_save";
import { fetch_standard_Playbooks } from "../Services/Fetch_standard_playbooks";
import Loader from "../Loader/Loader";
import AnalysisTab from "./AnalysesTab";
import React from "react";
import { fetchPlaybooks } from "../Services/FetchPlaybooks";

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`review-tabpanel-${index}`}
      aria-labelledby={`review-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ pt: 3 }}>{children}</Box>}
    </div>
  );
}

interface Props {
  mode: any;
}

export const ReviewTab: React.FC<Props> = ({ mode }) => {
  // --- STATE MANAGEMENT ---
  const [mainTab, setMainTab] = useState(0);
  const [innerTab, setInnerTab] = useState(0);
  const [standardPlaybooks, setStandardPlaybooks] = useState<Playbook[]>([]);
  const [customPlaybooks, setCustomPlaybooks] = useState<Playbook[]>([]);
  const [playbookToRun, setPlaybookToRun] = useState<Playbook | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newPlaybookName, setNewPlaybookName] = useState("");
  const [newPlaybookDesc, setNewPlaybookDesc] = useState("");
  const [targetPlaybookId, setTargetPlaybookId] = useState("");
  const [newRuleName, setNewRuleName] = useState("");
  const [newRuleInstruction, setNewRuleInstruction] = useState("");
  const [newRuleType, setNewRuleType] = useState<"Redline" | "Suggestion" | "Draft">("Suggestion");
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const [playbookIdToDelete, setPlaybookIdToDelete] = useState<string | null>(null);
  const [ruleDetailsDialogOpen, setRuleDetailsDialogOpen] = useState(false);
  const [currentRule, setCurrentRule] = useState<Rule | null>(null);
  const [editRuleDialogOpen, setEditRuleDialogOpen] = useState(false);
  const [editedRuleName, setEditedRuleName] = useState("");
  const [editedRuleInstruction, setEditedRuleInstruction] = useState("");
  const [editedRuleType, setEditedRuleType] = useState<"Redline" | "Suggestion" | "Draft">("Suggestion");
  const { enqueueSnackbar } = useSnackbar();

  // --- PLAYBOOK MANAGEMENT FUNCTIONS ---
  const handleFetchPlaybooks = async () => {
    setLoading(true);
    setError(null);
    try {
      const { customPlaybooks } = await fetchPlaybooks();
      const { standardPlaybooks } = await fetch_standard_Playbooks();
      
      // Add Blue1 rule to customPlaybooks if not exists
      const blue1Rule: Rule = {
        id: "rule-blue1",
        name: "Blue1",
        instruction: "Replace all instances of blue with yellow",
        responseType: "Redline",
        enabled: true,
        lastModified: new Date().toISOString(),
      };
      const hasBlue1 = customPlaybooks.some(pb => pb.rules.some(r => r.name === "Blue1"));
      if (!hasBlue1) {
        const targetPlaybook = customPlaybooks[0] || { id: `custom-${Date.now()}`, name: "Default Playbook", description: "", rules: [], readonly: false };
        targetPlaybook.rules = [...targetPlaybook.rules, blue1Rule];
        await updatePlaybook(targetPlaybook);
        customPlaybooks[0] = targetPlaybook;
      }

      setStandardPlaybooks(standardPlaybooks);
      setCustomPlaybooks(customPlaybooks);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to fetch playbooks.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    handleFetchPlaybooks();
  }, []);

  useEffect(() => {
    console.log('mode is :', mode);
    if (mode) {
      if (mode === 'playbook') {
        setMainTab(1);
      }
      if (mode === 'ai-review') {
        setMainTab(0);
      }
    }
  }, [mode]);

  const handleCreatePlaybook = async (): Promise<void> => {
    if (!newPlaybookName.trim()) {
      enqueueSnackbar("Playbook name is required.", { variant: "warning" });
      return;
    }
    setLoading(true);
    try {
      await createPlaybook({ id: `custom-${Date.now()}`, name: newPlaybookName, description: newPlaybookDesc, rules: [], readonly: false });
      setNewPlaybookName("");
      setNewPlaybookDesc("");
      await handleFetchPlaybooks();
      enqueueSnackbar("Playbook created!", { variant: "success" });
    } catch (err) {
      enqueueSnackbar(err instanceof Error ? err.message : "Failed to create.", { variant: "error" });
    } finally {
      setLoading(false);
    }
  };

  const handleAddRule = async (): Promise<void> => {
    if (!targetPlaybookId || !newRuleName.trim() || !newRuleInstruction.trim() || !newRuleType) {
      enqueueSnackbar("Please select a playbook, rule type, and fill all rule fields.", { variant: "warning" });
      return;
    }
    const target = customPlaybooks.find((pb) => pb.id === targetPlaybookId);
    if (!target) return;

    const newRule: Rule = { 
      id: `rule-${Date.now()}`, 
      name: newRuleName, 
      instruction: newRuleInstruction, 
      responseType: newRuleType, 
      enabled: true,
      lastModified: new Date().toISOString(),
    };
    const updated = { ...target, rules: [...target.rules, newRule] };
    setLoading(true);
    try {
      await updatePlaybook(updated);
      setTargetPlaybookId("");
      setNewRuleName("");
      setNewRuleInstruction("");
      setNewRuleType("Suggestion");
      await handleFetchPlaybooks();
      enqueueSnackbar("Rule added!", { variant: "success" });
    } catch (err) {
      enqueueSnackbar(err instanceof Error ? err.message : "Failed to add rule.", { variant: "error" });
    } finally {
      setLoading(false);
    }
  };

  const handleEditRule = async () => {
    if (!currentRule || !targetPlaybookId) return;
    const target = customPlaybooks.find((pb) => pb.id === targetPlaybookId);
    if (!target) return;

    const updatedRules = target.rules.map(rule => 
      rule.id === currentRule.id 
        ? { ...rule, name: editedRuleName, instruction: editedRuleInstruction, responseType: editedRuleType, lastModified: new Date().toISOString() }
        : rule
    );
    const updatedPlaybook = { ...target, rules: updatedRules };
    setLoading(true);
    try {
      await updatePlaybook(updatedPlaybook);
      await handleFetchPlaybooks();
      enqueueSnackbar("Rule updated!", { variant: "success" });
    } catch (err) {
      enqueueSnackbar(err instanceof Error ? err.message : "Failed to update rule.", { variant: "error" });
    } finally {
      setLoading(false);
      setEditRuleDialogOpen(false);
    }
  };

  const handleDeleteRule = async (playbookId: string, ruleId: string) => {
    const target = customPlaybooks.find((pb) => pb.id === playbookId);
    if (!target) return;

    const updatedRules = target.rules.filter(rule => rule.id !== ruleId);
    const updatedPlaybook = { ...target, rules: updatedRules };
    setLoading(true);
    try {
      await updatePlaybook(updatedPlaybook);
      await handleFetchPlaybooks();
      enqueueSnackbar("Rule deleted!", { variant: "success" });
    } catch (err) {
      enqueueSnackbar(err instanceof Error ? err.message : "Failed to delete rule.", { variant: "error" });
    } finally {
      setLoading(false);
      setRuleDetailsDialogOpen(false);
    }
  };

  const debouncedUpdatePlaybook = debounce(updatePlaybook, 500);

  const handleToggleCustomRule = async (playbookId: string, ruleId: string) => {
    let updatedPlaybook: Playbook | undefined;
    const updatedCustoms = customPlaybooks.map(pb => {
      if (pb.id === playbookId) {
        const rules = pb.rules.map(rule => 
          rule.id === ruleId 
            ? { ...rule, enabled: !rule.enabled, lastModified: new Date().toISOString() } 
            : rule
        );
        updatedPlaybook = { ...pb, rules };
        return updatedPlaybook;
      }
      return pb;
    });
    setCustomPlaybooks(updatedCustoms);
    if (updatedPlaybook) {
      try {
        await debouncedUpdatePlaybook(updatedPlaybook);
      } catch {
        enqueueSnackbar('Failed to sync toggle.', { variant: 'error' });
        handleFetchPlaybooks();
      }
    }
  };

  const handleToggleStandardRule = (playbookId: string, ruleId: string) => {
    setStandardPlaybooks(prev => prev.map(pb => pb.id === playbookId ? { ...pb, rules: pb.rules.map(rule => rule.id === ruleId ? { ...rule, enabled: !rule.enabled } : rule) } : pb));
  };

  const handleOpenDeleteDialog = (event: React.MouseEvent, playbookId: string) => {
    event.stopPropagation();
    setPlaybookIdToDelete(playbookId);
    setOpenDeleteDialog(true);
  };

  const handleConfirmDelete = async () => {
    if (!playbookIdToDelete) return;
    setLoading(true);
    try {
      await deletePlaybook(playbookIdToDelete);
      await handleFetchPlaybooks();
      enqueueSnackbar("Playbook deleted.", { variant: "info" });
    } catch (err) { 
      enqueueSnackbar(err instanceof Error ? err.message : "Deletion failed.", { variant: "error" });
    } finally {
      setLoading(false);
      setOpenDeleteDialog(false);
    }
  };

  const handleAnalysisComplete = (results: any) => {
    console.log("PlaybookTab: Analysis complete. Resetting trigger.", { resultsCount: results.length });
    setPlaybookToRun(null);
  };

  const openRuleDetails = (rule: Rule, playbookId: string) => {
    setCurrentRule(rule);
    setTargetPlaybookId(playbookId);
    setRuleDetailsDialogOpen(true);
  };

  const openEditRuleDialog = () => {
    if (currentRule) {
      setEditedRuleName(currentRule.name);
      setEditedRuleInstruction(currentRule.instruction);
      setEditedRuleType(currentRule.responseType as "Redline" | "Suggestion" | "Draft");
      setEditRuleDialogOpen(true);
    }
    setRuleDetailsDialogOpen(false);
  };

  const playbooksToShow = innerTab === 0 ? standardPlaybooks : customPlaybooks;

  return (
    <div>
      <Box sx={{ borderBottom: 1, borderColor: 'divider', display: 'flex', justifyContent: 'center', width: '100%' }}>
        <Tabs value={mainTab} onChange={(_, val) => setMainTab(val)} aria-label="Review tabs" style={{ width: '100%' }}>
          <Tab label="Analysis" id="review-tab-0" style={{ width: '50%' }} />
          <Tab label="Playbooks" id="review-tab-1" style={{ width: '50%' }} />
        </Tabs>
      </Box>
      <TabPanel value={mainTab} index={0}>
        <AnalysisTab
          playbookToRun={playbookToRun}
          onAnalysisComplete={handleAnalysisComplete}
        />
      </TabPanel>
      <TabPanel value={mainTab} index={1}>
        {loading && <Loader />}
        <Typography width={'100%'} textAlign={'center'} fontWeight={'500'}>
          Playbooks
        </Typography>
        <p style={{ width: '100%', textAlign: 'center', fontFamily: 'initial' }}>
          You can create/Update/delete playbook and run these in analyses Tab.
        </p>
        {error && <Alert severity="error" sx={{ my: 2 }}>{error}</Alert>}
        <Tabs value={innerTab} onChange={(_, val) => setInnerTab(val)} sx={{ my: 2, ".MuiTabs-indicator": { backgroundColor: "#16e7ff7d" }, ".MuiTab-root": { color: "rgba(255,255,255,0.7)" }, ".Mui-selected": { color: "#fff !important" } }}>
          <Tab label="Standard" style={{ width: '50%' }} />
          <Tab label="Custom" style={{ width: '50%' }} />
        </Tabs>
        <Box sx={{ maxHeight: "60vh", overflowY: "auto", pr: 1 }}>
          {playbooksToShow.map((pb) => (
            <Accordion key={pb.id} sx={{ background: "rgba(0,0,0,0.2)", color: "white", mb: 1 }}>
              <AccordionSummary expandIcon={<ExpandMore sx={{ color: "white" }} />}>
                <Typography sx={{ fontWeight: "bold", flexGrow: 1 }}>{pb.name}</Typography>
                {innerTab === 1 && <Button size="small" color="error" startIcon={<DeleteIcon />} onClick={(e) => handleOpenDeleteDialog(e, pb.id)} disabled={loading}>Delete</Button>}
              </AccordionSummary>
              <AccordionDetails sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
                <Typography variant="body2" sx={{ mb: 1 }}>{pb.description}</Typography>
                {pb.rules.map((rule: Rule) => (
                  <Box 
                    key={rule.id} 
                    sx={{ p: 1, borderRadius: 1, background: 'rgba(255,255,255,0.05)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}
                    onClick={() => openRuleDetails(rule, pb.id)}
                  >
                    <Typography variant="body2" sx={{ cursor: 'pointer' }}>{rule.name} ({rule.responseType})</Typography>
                    <Switch 
                      checked={rule.enabled} 
                      onChange={() => innerTab === 0 ? handleToggleStandardRule(pb.id, rule.id) : handleToggleCustomRule(pb.id, rule.id)} 
                      size="small" 
                      disabled={loading} 
                    />
                  </Box>
                ))}
                <PulsingButton
                  startIcon={loading ? <CircularProgress size={20} /> : <SendIcon />}
                  sx={{ mt: 2 }}
                  onClick={() => {
                    setPlaybookToRun(pb);
                    setMainTab(0);
                  }}
                  disabled={loading || pb.rules.filter((r: any) => r.enabled).length === 0}
                >
                  Run with Rules
                </PulsingButton>
              </AccordionDetails>
            </Accordion>
          ))}
        </Box>
        <Box hidden={innerTab !== 1} sx={{ mt: 3, borderTop: '1px solid rgba(255,255,255,0.2)', pt: 3 }}>
          <Accordion sx={{ background: "rgba(0,0,0,0.4)", color: "white", mb: 2 }}>
            <AccordionSummary expandIcon={<AddIcon sx={{ color: "white" }} />}>
              <Typography fontWeight="bold">Create New Playbook</Typography>
            </AccordionSummary>
            <AccordionDetails sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
              <TextField label="Playbook Name" variant="filled" value={newPlaybookName} onChange={e => setNewPlaybookName(e.target.value)} />
              <TextField label="Description" variant="filled" value={newPlaybookDesc} onChange={e => setNewPlaybookDesc(e.target.value)} />
              <Button variant="outlined" sx={{ color: '#16e7ff7d', borderColor: '#16e7ff7d' }} onClick={handleCreatePlaybook} disabled={loading}>Create</Button>
            </AccordionDetails>
          </Accordion>
          <Accordion sx={{ background: "rgba(0,0,0,0.4)", color: "white" }}>
            <AccordionSummary expandIcon={<AddIcon sx={{ color: "white" }} />}>
              <Typography fontWeight="bold">Add New Rule</Typography>
            </AccordionSummary>
            <AccordionDetails sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
              <FormControl variant="filled" fullWidth>
                <InputLabel sx={{ color: "rgba(255,255,255,0.7)" }}>Add Rule to Playbook</InputLabel>
                <Select value={targetPlaybookId} onChange={e => setTargetPlaybookId(e.target.value)} sx={{ color: 'white' }}>
                  <MenuItem value="" disabled>Select a playbook</MenuItem>
                  {customPlaybooks.map(pb => <MenuItem key={pb.id} value={pb.id}>{pb.name}</MenuItem>)}
                </Select>
              </FormControl>
              <TextField label="Rule Name" variant="filled" value={newRuleName} onChange={e => setNewRuleName(e.target.value)} />
              <FormControl variant="filled" fullWidth>
                <InputLabel sx={{ color: "rgba(255,255,255,0.7)" }}>Rule Type</InputLabel>
                <Select 
                  value={newRuleType} 
                  onChange={e => setNewRuleType(e.target.value as "Redline" | "Suggestion" | "Draft")} 
                  sx={{ color: 'white' }}
                >
                  <MenuItem value="Redline">Redline</MenuItem>
                  <MenuItem value="Suggestion">Suggestion</MenuItem>
                  <MenuItem value="Draft">Draft</MenuItem>
                </Select>
              </FormControl>
              <TextField 
                label="Instruction for AI" 
                variant="filled" 
                multiline 
                rows={2} 
                value={newRuleInstruction} 
                onChange={e => setNewRuleInstruction(e.target.value)} 
              />
              <Button 
                variant="outlined" 
                sx={{ color: '#16e7ff7d', borderColor: '#16e7ff7d' }} 
                onClick={handleAddRule} 
                disabled={loading}
              >
                Save Rule
              </Button>
            </AccordionDetails>
          </Accordion>
        </Box>
      </TabPanel>
      <Dialog open={openDeleteDialog} onClose={() => setOpenDeleteDialog(false)}>
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent><Typography>Are you sure you want to delete this playbook?</Typography></DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDeleteDialog(false)}>Cancel</Button>
          <Button onClick={handleConfirmDelete} color="error" disabled={loading}>Delete</Button>
        </DialogActions>
      </Dialog>
      <Dialog open={ruleDetailsDialogOpen} onClose={() => setRuleDetailsDialogOpen(false)} fullWidth maxWidth="sm">
        <DialogTitle>Rule Details</DialogTitle>
        <DialogContent>
          {currentRule && (
            <>
              <Typography variant="body1"><strong>Rule Name:</strong> {currentRule.name}</Typography>
              <Typography variant="body1"><strong>Rule Type:</strong> {currentRule.responseType}</Typography>
              <Typography variant="body1"><strong>Instruction:</strong> {currentRule.instruction}</Typography>
              <Typography variant="body1"><strong>Last Modified:</strong> {currentRule.lastModified || 'N/A'}</Typography>
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setRuleDetailsDialogOpen(false)}>Close</Button>
          <Button onClick={openEditRuleDialog} disabled={loading}>Edit</Button>
          <Button 
            color="error" 
            onClick={() => handleDeleteRule(targetPlaybookId, currentRule?.id || '')} 
            disabled={loading}
          >
            Delete
          </Button>
        </DialogActions>
      </Dialog>
      <Dialog open={editRuleDialogOpen} onClose={() => setEditRuleDialogOpen(false)} fullWidth maxWidth="sm">
        <DialogTitle>Edit Rule</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            margin="dense"
            label="Rule Name"
            value={editedRuleName}
            onChange={(e) => setEditedRuleName(e.target.value)}
          />
          <FormControl variant="filled" fullWidth sx={{ mt: 2 }}>
            <InputLabel>Rule Type</InputLabel>
            <Select 
              value={editedRuleType} 
              onChange={(e) => setEditedRuleType(e.target.value as "Redline" | "Suggestion" | "Draft")}
            >
              <MenuItem value="Redline">Redline</MenuItem>
              <MenuItem value="Suggestion">Suggestion</MenuItem>
              <MenuItem value="Draft">Draft</MenuItem>
            </Select>
          </FormControl>
          <TextField
            fullWidth
            multiline
            rows={2}
            margin="dense"
            label="Instruction"
            value={editedRuleInstruction}
            onChange={(e) => setEditedRuleInstruction(e.target.value)}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditRuleDialogOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleEditRule}>Save</Button>
        </DialogActions>
      </Dialog>
    </div>
  );
};