interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

const TabPanel = memo(function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      style={{ width: '100%', height: '100%' }}
      {...other}
    >
      {value === index && (
        <Fade in={true} timeout={500}>
          <Box sx={{ p: '7px', height: '100%' }}>{children}</Box>
        </Fade>
      )}
    </div>
  );
});

async function getDocumentContent(): Promise<string> {
  try {
    return await Word.run(async (context) => {
      const body = context.document.body;
      body.load("text");
      await context.sync();
      console.log("Office.js: Retrieved document text.");
      return body.text;
    });
  } catch (error) {
    console.error("Office.js Error (getDocumentContent):", error);
    return "This is simulated document text because Office.js is not running.";
  }
}

async function insertText(text: string): Promise<void> {
  try {
    await Word.run(async (context) => {
      const range = context.document.getSelection();
      range.insertText(text, Word.InsertLocation.replace);
      await context.sync();
      console.log("Office.js: Inserted text.");
    });
  } catch (error) {
    console.error("Office.js Error (insertText):", error);
    alert(`Simulated Insert: "${text}"`);
  }
}

class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { hasError: boolean }> {
  state = { hasError: false };
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  render() {
    if (this.state.hasError) {
      return <Box sx={{ p: 2, color: '#fff' }}>Something went wrong. Please refresh.</Box>;
    }
    return this.props.children;
  }
}

function WordAddIn() {
  const [activeTab, setActiveTab] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [playbookToRun, setPlaybookToRun] = useState<Playbook | null>(null);
  const [mode, setMode] = useState<string | undefined>(undefined);




  const handleTabChange = (__event: React.SyntheticEvent, newValue: number) => {
    setActiveTab(newValue);
  };

  const handleRunPlaybook = (playbook: Playbook) => {
    console.log(`WordAddIn: Received command to run playbook '${playbook.name}'.`);
    setIsLoading(true);
    setPlaybookToRun(playbook);
    setActiveTab(2); // Switch to Analysis tab
  };

  const handleAnalysisComplete = () => {
    console.log("WordAddIn: Analysis complete. Resetting state.");
    setIsLoading(false);
    setPlaybookToRun(null);
  };

  return (
    <Box sx={{ height: '100vh', width: '100%', maxWidth: { xs: 375, sm: 600, md: 800 }, margin: '0 auto', background: PRIMARY_GRADIENT, display: 'flex', flexDirection: 'column' }}>
      <ButtonAppBar />
      <Box sx={{ borderBottom: 1, borderColor: 'rgba(255, 255, 255, 0.2)', background: 'rgba(0,0,0,0.2)', backdropFilter: 'blur(5px)', flexShrink: 0 }}>
        <Tabs
          value={activeTab}
          onChange={handleTabChange}
          variant="fullWidth"
          aria-label="Main navigation tabs"
          sx={{
            '& .MuiTabs-indicator': { backgroundColor: '#fff', height: '3px' },
            '& .MuiTab-root': { color: 'rgba(255,255,255,0.7)', fontWeight: 'bold' },
            '& .Mui-selected': { color: '#fff !important' }
          }}
        >
          <Tab icon={<HomeIcon />} label="Home" aria-label="Home tab" />
          <Tab icon={<BoltIcon />} label="Assistant" aria-label="Assistant tab" />
          {/* <Tab icon={<ScienceIcon />} label="Analysis" aria-label="Analysis tab" /> */}
          <Tab icon={<AutoStoriesIcon />} label="Review" aria-label="Playbook tab" />
        </Tabs>
      </Box>
      <Box sx={{ flexGrow: 1, overflowY: 'auto', scrollbarWidth: "none" }}>
        <TabPanel value={activeTab} index={0}>
          <HomeTab setActiveTab={setActiveTab} setMode={setMode}  />
        </TabPanel>
        <TabPanel value={activeTab} index={1}>
          <AssistantTab mode={mode}  />
        </TabPanel>
        {/* <TabPanel value={activeTab} index={2}>
          <AnalysisTab
            playbookToRun={playbookToRun}
            onAnalysisComplete={handleAnalysisComplete}
          />
        </TabPanel> */}
        <TabPanel value={activeTab} index={2}>
          <ReviewTab
            // onRunPlaybook={handleRunPlaybook}
            // isLoading={isLoading}
            mode={mode}
          />
        </TabPanel>
      </Box>
    </Box>
  );
}

