import { keyframes } from "@emotion/react";
import { Button, Card, styled } from "@mui/material";

export const LIGHT_SHADOW = '0px 4px 12px rgba(0, 0, 0, 0.1)';
export const DARK_SHADOW = '0px 6px 18px rgba(0, 0, 0, 0.2)';
 export const PRIMARY_GRADIENT = 'linear-gradient(160deg, #16e7ff7d, #020204)';    
   export const bounceAnimation = keyframes`0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); }`;
  export  const glowAnimation = keyframes`0% { box-shadow: 0 0 3px #16e7ff7d; } 50% { box-shadow: 0 0 15px #16e7ff7d; } 100% { box-shadow: 0 0 3px #16e7ff7d; }`;
 export   const underlineSweep = keyframes`from { width: 0; } to { width: 100%; }`;
export const GradientButton = styled(Button)({ background: PRIMARY_GRADIENT, color: 'white', fontWeight: 'bold', borderRadius: '12px', padding: '10px 20px', boxShadow: LIGHT_SHADOW, textTransform: 'none', fontSize: '1rem', transition: 'all 0.3s ease', '&:hover': { boxShadow: DARK_SHADOW, transform: 'translateY(-2px)', filter: 'brightness(1.1)' }});
 export const PulsingButton = styled(GradientButton)({ border: '2px solid transparent', '&:hover': { animation: `${glowAnimation} 1.5s infinite ease-in-out` } });
 export const RedlineText = styled('span')({ position: 'relative', color: '#ff5252', fontWeight: 'bold', '&::after': { content: '""', position: 'absolute', bottom: '-2px', left: 0, height: '2px', backgroundColor: '#ff5252', animation: `${underlineSweep} 0.5s ease-out forwards` } });
export const SECONDARY_GRADIENT = 'linear-gradient(45deg, rgba(52, 122, 122, 1)7d, #3a7b837d)';

export const GlassmorphicCard = styled(Card)({ padding: '16px', borderRadius: '16px', backgroundColor: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255, 255, 255, 0.2)', boxShadow: LIGHT_SHADOW });
 export const SendButton = styled(GradientButton)({ '&:hover': { animation: `${bounceAnimation} 0.4s ease` } });
