import * as stringSimilarity from "string-similarity";
import React, { FC, useState, useEffect, useRef } from "react";
import {
  Typography,
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Grow,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Button,
  Card,
  Dialog,
  DialogActions,
  DialogTitle,
  Alert,
  Paper,
  Stack,
  Snackbar,
  AlertTitle,
  Chip,
  DialogContent,
} from "@mui/material";
import Grid from "@mui/material/Grid";
import {
  ExpandMore,
  Science,
  Edit,
  Cancel,
  CheckCircle,
  Delete as DeleteIcon,
} from "@mui/icons-material";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import { OpenAICall } from "../Services/OpenAI_API_Call";
import { StoreClause, UpdateClauseAnchor } from "../Services/StoreClause";
import { GlassmorphicCard, GradientButton, RedlineText, SECONDARY_GRADIENT } from "../Utils/styles";
import { supabase } from "../Services/supabaseClient";

// Type definition for a single analysis result
interface IAnalysisResult {
  uniqueId: number;
  ruleName: string;
  isCompliant: boolean;
  reason: string;
  suggestion: string;
  highlightText?: string;
  contextText?: string;
  status: "pending" | "applied" | "ignored";
  responseType: string;
  instruction: string;
  ruleId: string;
  clauseInstanceId?: string | null;
  contentControlTag?: string | null;
  isLoading?: boolean; // Added for per-result loading state
}

// Type definition for Playbook
interface IPlaybook {
  id: string;
  name: string;
  rules: {
    enabled: boolean;
    instruction: string;
    name: string;
    responseType: string;
    id: string;
    lastModified?: string;
  }[];
}

// Props for the component
interface AnalysisTabProps {
  playbookToRun: IPlaybook | null;
  onAnalysisComplete: (results: RuleResponse[]) => void;
}

// Define RuleResponse to match client requirement
interface RuleResponse {
  ruleName: string;
  isCompliant: boolean;
  reason: string;
  suggestion: string;
  highlightText?: string;
  responseType: string;
  instruction: string;
}

const AnalysisTab: FC<AnalysisTabProps> = ({ playbookToRun, onAnalysisComplete }) => {
  // --- STATE MANAGEMENT ---
  const [contractType, setContractType] = useState("");
  const [partyRole, setPartyRole] = useState("");
  const [concerns, setConcerns] = useState("");
  const [results, setResults] = useState<IAnalysisResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [uiMessage, setUiMessage] = useState<string>("Run an analysis to see results here.");
  const [notification, setNotification] = useState<{
    open: boolean;
    message: string;
    severity: "success" | "error";
  } | null>(null);
  const [expandedResultId, setExpandedResultId] = useState<number | null>(null);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [currentResultForEdit, setCurrentResultForEdit] = useState<IAnalysisResult | null>(null);
  const [editedSuggestion, setEditedSuggestion] = useState("");
  const [editedRuleName, setEditedRuleName] = useState("");
  const [editedInstruction, setEditedInstruction] = useState("");
  const [editedResponseType, setEditedResponseType] = useState<"Redline" | "Suggestion" | "Draft">(
    "Suggestion"
  );
  const [clauseInstanceIds, setClauseInstanceIds] = useState<string[]>([]);
  const analysisIdRef = useRef(0);

  useEffect(() => {
    console.log("AnalysisTab: playbookToRun received:", playbookToRun);
    if (playbookToRun) {
      console.log("AnalysisTab: Starting analysis with playbook ID:", playbookToRun.id);
      handleStart();
    } else {
      console.warn("AnalysisTab: No playbookToRun provided");
    }
  }, [playbookToRun]);

  useEffect(() => {
    return () => {
      clearAllHighlights();
    };
  }, []);

  // --- CORE FUNCTIONS ---
  const extractParagraphs = async (): Promise<string[]> => {
    return await Word.run(async (context) => {
      const paragraphs = context.document.body.paragraphs;
      paragraphs.load("items/text");
      await context.sync();
      return paragraphs.items.map((p) => p.text.trim()).filter((text) => text !== "");
    });
  };

  const findTextRange = async (
    context: Word.RequestContext,
    result: IAnalysisResult
  ): Promise<Word.Range | null> => {
    const { contextText, highlightText } = result;
    if (!highlightText) return null;

    try {
      const searchTarget = contextText || highlightText;
      const contextSearchResults = context.document.body.search(searchTarget, {
        matchCase: false,
        matchWholeWord: false,
      });
      contextSearchResults.load("items");
      await context.sync();
      if (contextSearchResults.items.length > 0) {
        const contextRange = contextSearchResults.items[0];
        if (contextText) {
          const highlightSearchResults = contextRange.search(highlightText, {
            matchCase: false,
            matchWholeWord: result.responseType === "Redline",
          });
          highlightSearchResults.load("items");
          await context.sync();
          if (highlightSearchResults.items.length > 0) {
            return highlightSearchResults.items[0];
          }
        } else {
          return contextRange;
        }
      }
    } catch (error) {
      console.warn("Exact search failed, falling back to fuzzy search. Error:", error);
    }

    console.log(`Fuzzy search fallback for: "${highlightText}"`);
    const paragraphs = context.document.body.paragraphs;
    paragraphs.load("items/text");
    await context.sync();

    const paragraphTexts = paragraphs.items.map((p) => p.text);
    const searchContext = contextText || highlightText;

    const bestMatch = stringSimilarity.findBestMatch(searchContext, paragraphTexts);

    if (bestMatch.bestMatch.rating > 0.7) {
      const bestParagraph = paragraphs.items[bestMatch.bestMatchIndex];
      const highlightSearchResults = bestParagraph.search(highlightText, {
        matchCase: false,
        matchWholeWord: result.responseType === "Redline",
      });
      highlightSearchResults.load("items");
      await context.sync();
      if (highlightSearchResults.items.length > 0) {
        console.log("Fuzzy search succeeded!");
        return highlightSearchResults.items[0];
      }
    }

    console.error("Fuzzy search also failed to find a confident match.");
    return null;
  };

  const buildPrompt = (fullDoc: string, currentPlaybook: IPlaybook | null): string => {
    const escapedText = fullDoc.replace(/"/g, '\\"').replace(/\n/g, "\\n");

    const baseInstructions = `
You are a meticulous and precise document analysis engine. Your primary goal is to identify every single violation of the given rules and report each one individually.

**CRITICAL RULES FOR YOUR RESPONSE:**
1. **JSON Array Only:** Your entire response MUST be a single, minified JSON array.
2. **ONE OBJECT PER VIOLATION:** You MUST create a separate JSON object for EACH individual violation.
3. **VERBATIM TEXT ONLY:** The 'highlightText' field must be an EXACT copy of the non-compliant text.
4. **SINGLE REPLACEMENT:** The 'suggestion' field must contain the replacement for ONLY its corresponding 'highlightText'.
5. **CONTEXT IS KEY:** The 'contextText' field must be the full sentence containing the 'highlightText'.
6. **NO IDENTICAL SUGGESTIONS:** If a 'suggestion' is identical to the 'highlightText', do NOT create a JSON object for it.
7. **INCLUDE RULE DETAILS:** Include 'responseType', 'instruction', and 'ruleId' for each rule violation.
8. **CONSISTENT RULE NAMES:** Ensure 'ruleName' is consistent across all violations of the same rule, matching the playbook rule name exactly.
9. **REDLINE CONSISTENCY:** For rules with responseType "Redline", identify ALL instances of the same violation in the document.

**JSON Object Structure:**
- "ruleName": (string) The name of the specific rule that was violated, matching the playbook rule name.
- "isCompliant": (boolean) MUST be 'false' for any reported issue.
- "reason": (string) A brief explanation of the error.
- "suggestion": (string) The corrected word or phrase.
- "highlightText": (string) The incorrect word or phrase.
- "contextText": (string) The full sentence where the 'highlightText' was found.
- "responseType": (string) The type of rule ("Redline", "Suggestion", "Draft").
- "instruction": (string) The AI instruction for the rule.
- "ruleId": (string) The ID of the rule.

**EXAMPLE:**
[
  {"ruleName":"Blue1","isCompliant":false,"reason":"Found 'blue' which should be 'yellow'.","suggestion":"yellow","highlightText":"blue","contextText":"The sky is blue today.","responseType":"Redline","instruction":"Replace all instances of blue with yellow","ruleId":"rule-blue1"},
  {"ruleName":"Blue1","isCompliant":false,"reason":"Found 'blue' which should be 'yellow'.","suggestion":"yellow","highlightText":"blue","contextText":"The sea is blue.","responseType":"Redline","instruction":"Replace all instances of blue with yellow","ruleId":"rule-blue1"}
]`.trim();

    if (currentPlaybook && currentPlaybook.rules.length > 0) {
      const rulesText = currentPlaybook.rules
        .filter((r) => r.enabled)
        .map(
          (r, i) => `${i + 1}. Rule: "${r.instruction}" (Type: ${r.responseType}, Rule ID: ${r.id}, Rule Name: ${r.name})`
        )
        .join("\n");
      return `${baseInstructions}\n\nAnalyze the document using these playbook rules:\n${rulesText}\n\nDocument Text:\n"""\n${escapedText}\n"""`;
    }
    return `${baseInstructions}\n\nAnalyze the document for general quality and correctness. Use the following context if provided:\nContract Type: ${contractType || "None"}\nVoice or Perspective: ${partyRole || "None"}\nSpecific Concerns: ${concerns || "None"}\nBased on the concerns, choose responseType: "Redline" for text replacements, "Suggestion" for suggestions, "Draft" for drafting new text.\nIf the concerns specify a replacement, treat it as a rule and find all instances.\n\nDocument Text:\n"""\n${escapedText}\n"""`;
  };

  const handleStart = async (currentPlaybook: IPlaybook | null = playbookToRun) => {
    const currentAnalysisId = ++analysisIdRef.current;

    setIsLoading(true);
    setResults([]);
    setUiMessage("");
    await clearAllHighlights();

    try {
      if (!currentPlaybook) {
        throw new Error("No playbook selected for analysis.");
      }

      const paragraphs = await extractParagraphs();
      if (paragraphs.length === 0) {
        setUiMessage("Document is empty. Please add text to analyze.");
        setIsLoading(false);
        return;
      }

      const fullText = paragraphs.join("\n\n");
      const prompt = buildPrompt(fullText, currentPlaybook);
      const aiResponse = await OpenAICall(prompt);

      if (currentAnalysisId !== analysisIdRef.current) {
        console.log("A newer analysis has started. Aborting state update for this old one.");
        return;
      }

      let rawJson = "[]";
      const content = aiResponse?.choices?.[0]?.message?.content;
      if (content) {
        const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```|(\[[\s\S]*\])/);
        rawJson = jsonMatch ? jsonMatch[1] || jsonMatch[2] : content;
      }

      console.log("AI Response Raw JSON:", rawJson);

      const parsedResults = JSON.parse(rawJson) as IAnalysisResult[];

      if (!Array.isArray(parsedResults)) {
        throw new Error("AI response was not a valid JSON array. Please try again.");
      }

      console.log("Parsed AI Results:", parsedResults);
      console.log("Playbook Rules:", currentPlaybook.rules);

      const resultsWithIds: IAnalysisResult[] = parsedResults.map((r, i) => {
        const rule = currentPlaybook?.rules.find(
          (rule) => rule.name === r.ruleName || rule.instruction === r.ruleName
        );
        if (!rule) {
          console.warn(`Rule "${r.ruleName}" not found in playbook. Using fallback rule ID.`);
          return {
            ...r,
            uniqueId: i,
            status: "pending",
            ruleId: "fallback-rule-id",
            clauseInstanceId: null,
            contentControlTag: null,
            responseType: r.responseType || "Suggestion",
            isLoading: false,
          };
        }
        return {
          ...r,
          uniqueId: i,
          status: "pending",
          ruleId: rule.id,
          clauseInstanceId: null,
          contentControlTag: null,
          ruleName: rule.name,
          responseType: rule.responseType,
          isLoading: false,
        };
      });

      // Group Redline results by ruleName and highlightText for consistency
      const grouped: Record<string, IAnalysisResult[]> = resultsWithIds.reduce((acc, r) => {
        if (r.responseType === "Redline" && r.highlightText) {
          const key = `${r.ruleName.trim()}_${r.highlightText.trim()}`;
          if (!acc[key]) acc[key] = [];
          acc[key].push(r);
        }
        return acc;
      }, {});

      console.log("Grouped Results:", grouped);

      const consolidated: IAnalysisResult[] = [];
      let consolidatedIdOffset = resultsWithIds.length;
      for (const [key, group] of Object.entries(grouped)) {
        if (group.length > 1) {
          const first = group[0];
          console.log(`Consolidating group for key: ${key}, count: ${group.length}`);
          consolidated.push({
            uniqueId: consolidatedIdOffset++,
            ruleName: `${first.ruleName} (All)`,
            isCompliant: false,
            reason: `Found ${group.length} instances of "${first.highlightText}" to replace with "${first.suggestion}".`,
            suggestion: first.suggestion,
            highlightText: first.highlightText,
            contextText: undefined,
            status: "pending",
            responseType: "Redline",
            instruction: first.instruction,
            ruleId: first.ruleId,
            clauseInstanceId: null,
            contentControlTag: null,
            isLoading: false,
          });
        }
      }

      console.log("Consolidated Grouped Results:", consolidated);

      const finalResults = [...resultsWithIds, ...consolidated];
      setResults(finalResults);

      if (finalResults.length > 0) {
        console.log(
          "Analysis results with ruleIds:",
          finalResults.map((r) => ({ ruleName: r.ruleName, ruleId: r.ruleId, responseType: r.responseType }))
        );
        onAnalysisComplete(finalResults);
      } else {
        setUiMessage("No compliance issues found. Great work!");
        onAnalysisComplete([]);
      }
    } catch (err: any) {
      console.error("Error during analysis:", err);
      const errorMessage = `An error occurred: ${err.message || "Please check the console for details."}`;
      setUiMessage(errorMessage);
      setNotification({ open: true, message: errorMessage, severity: "error" });
    } finally {
      if (currentAnalysisId === analysisIdRef.current) {
        setIsLoading(false);
      }
    }
  };

  const highlightResultsInDocument = async (result: IAnalysisResult) => {
    try {
      await Word.run(async (context) => {
        if (result.contextText) {
          const targetRange = await findTextRange(context, result);
          if (targetRange) {
            targetRange.load("font");
            await context.sync();
            targetRange.font.highlightColor = "#FFFF00";
          }
        } else {
          const highlightSearchResults = context.document.body.search(result.highlightText!, {
            matchCase: false,
            matchWholeWord: result.responseType === "Redline",
          });
          highlightSearchResults.load("items/font");
          await context.sync();
          for (const range of highlightSearchResults.items) {
            range.load("font");
            await context.sync();
            if (!range.font.strikeThrough) {
              range.font.highlightColor = "#FFFF00";
            }
          }
        }
        await context.sync();
      });
    } catch (error) {
      console.error("Error highlighting result:", error);
    }
  };

  const clearAllHighlights = async () => {
    try {
      await Word.run(async (context) => {
        context.document.body.font.highlightColor = null;
        await context.sync();
      });
    } catch (e) {
      console.error("Could not clear highlights", e);
    }
  };

  const normalizeTextForCompare = (text?: string): string => {
    if (!text) return "";
    return text.trim().toLowerCase();
  };

  const handleApply = async (result: IAnalysisResult): Promise<void> => {
    try {
      // Validate input
      if (!result.highlightText || !result.suggestion) {
        throw new Error("Cannot apply: Missing highlightText or suggestion.");
      }

      if (!result.ruleId) {
        throw new Error(`Cannot apply: No ruleId provided for rule "${result.ruleName}".`);
      }

      // Normalize and compare texts to prevent applying identical suggestions
      const normalizedHighlight = normalizeTextForCompare(result.highlightText);
      const normalizedSuggestion = normalizeTextForCompare(result.suggestion);
      if (normalizedHighlight === normalizedSuggestion) {
        console.warn(`Suggestion "${result.suggestion}" is identical to highlightText "${result.highlightText}". Ignoring.`);
        await handleIgnore(result);
        return;
      }

      // Set loading state for this result
      setResults((prev) =>
        prev.map((r) =>
          r.uniqueId === result.uniqueId ? { ...r, isLoading: true } : r
        )
      );

      let appliedCount = 0;
      let appliedClauseInstanceIds: string[] = [];
      let appliedContentControlTags: string[] = [];

      await Word.run(async (context) => {
        const isGroupedResult = result.ruleName.endsWith("(All)");
        const isRedline = result.responseType === "Redline";

        if (isGroupedResult || (isRedline && !result.contextText)) {
          // Iterative approach for global/multi replacements (e.g., Redline All or global Redline)
          let iterationCount = 0;
          const maxIterations = 500;

          while (iterationCount < maxIterations) {
            iterationCount++;

            let searchResults;
            if (result.contextText) {
              const contextSearch = context.document.body.search(result.contextText, {
                matchCase: false,
                matchWholeWord: false,
              });
              contextSearch.load("items");
              await context.sync();
              if (contextSearch.items.length === 0) break;

              const contextRange = contextSearch.items[0];
              searchResults = contextRange.search(result.highlightText!, {
                matchCase: false,
                matchWholeWord: isRedline,
              });
            } else {
              searchResults = context.document.body.search(result.highlightText!, {
                matchCase: false,
                matchWholeWord: isRedline,
              });
            }

            searchResults.load("items");
            await context.sync();

            if (searchResults.items.length === 0) {
              if (iterationCount === 1) {
                console.warn(`No exact matches found for "${result.highlightText}". Attempting fuzzy search fallback.`);
                const paragraphs = context.document.body.paragraphs;
                paragraphs.load("items/text");
                await context.sync();

                const paragraphTexts = paragraphs.items.map((p) => p.text);
                const searchContext = result.contextText || result.highlightText!;
                const bestMatch = stringSimilarity.findBestMatch(searchContext, paragraphTexts);

                if (bestMatch.bestMatch.rating > 0.7) {
                  const bestParagraph = paragraphs.items[bestMatch.bestMatchIndex];
                  searchResults = bestParagraph.search(result.highlightText!, {
                    matchCase: false,
                    matchWholeWord: isRedline,
                  });
                  searchResults.load("items");
                  await context.sync();
                }
              }
              if (searchResults.items.length === 0) break;
            }

            for (const range of searchResults.items) {
              range.load("font");
            }
            await context.sync();

            let foundApplicable = false;
            for (const range of searchResults.items) {
              if (range.font.strikeThrough && isRedline) {
                console.log(`Skipping already struck-through text: "${result.highlightText}"`);
                continue;
              }

              range.font.strikeThrough = true;
              range.font.color = "#C62828";
              const spaceRange = range.insertText(" ", "After");
              const newRange = spaceRange.insertText(result.suggestion, "After");
              newRange.font.bold = true;
              newRange.font.color = "#2E7D32";
              newRange.font.underline = "Single";
              newRange.font.highlightColor = null;

              const contentControlTag = `clause_${appliedCount + 1}_${result.uniqueId}_${Date.now()}`;
              const { data, error } = await StoreClause({
                clause_text: result.suggestion,
                source_type: "playbook",
                reason: result.reason,
                rule_id: result.ruleId,
                user_id: (await supabase.auth.getUser()).data.user?.id || "",
                anchor_tag_id: contentControlTag,
              });

              if (error) {
                throw new Error(`Failed to save clause: ${error.message}`);
              }

              if (!data?.clauseInstanceId) {
                throw new Error("Clause saved but no clauseInstanceId returned.");
              }

              const contentControl = newRange.insertContentControl();
              contentControl.tag = contentControlTag;
              contentControl.title = `Clause ${data.clauseInstanceId}`;
              contentControl.cannotEdit = true;
              contentControl.appearance = Word.ContentControlAppearance.hidden;

              const { error: anchorError } = await UpdateClauseAnchor(data.clauseInstanceId, contentControlTag);
              if (anchorError) {
                throw new Error(`Failed to update anchor tag for clause ID ${data.clauseInstanceId}: ${anchorError.message}`);
              }

              appliedClauseInstanceIds.push(data.clauseInstanceId);
              appliedContentControlTags.push(contentControlTag);
              appliedCount++;
              foundApplicable = true;

              await context.sync();
              break;
            }

            if (!foundApplicable) {
              break;
            }
          }

          if (iterationCount >= maxIterations) {
            console.warn(`Reached max iterations (${maxIterations}) for applying "${result.highlightText}". Possible loop issue.`);
          }
        } else {
          let searchResults = result.contextText
            ? context.document.body.search(result.contextText, {
                matchCase: false,
                matchWholeWord: false,
              })
            : context.document.body.search(result.highlightText!, {
                matchCase: false,
                matchWholeWord: isRedline,
              });

          context.load(searchResults, "items/font");
          await context.sync();

          if (searchResults.items.length === 0) {
            console.warn(`No exact matches found for "${result.highlightText}". Attempting fuzzy search.`);
            const paragraphs = context.document.body.paragraphs;
            paragraphs.load("items/text");
            await context.sync();

            const paragraphTexts = paragraphs.items.map((p) => p.text);
            const searchContext = result.contextText || result.highlightText!;
            const bestMatch = stringSimilarity.findBestMatch(searchContext, paragraphTexts);

            if (bestMatch.bestMatch.rating > 0.7) {
              const bestParagraph = paragraphs.items[bestMatch.bestMatchIndex];
              searchResults = bestParagraph.search(result.highlightText!, {
                matchCase: false,
                matchWholeWord: isRedline,
              });
              context.load(searchResults, "items/font");
              await context.sync();
            }

            if (searchResults.items.length === 0) {
              throw new Error(`No matches found for text: "${result.highlightText}" after fuzzy search.`);
            }
          }

          const rangesToProcess = [];
          for (let range of searchResults.items) {
            if (result.contextText) {
              const highlightSearchResults = range.search(result.highlightText!, {
                matchCase: false,
                matchWholeWord: isRedline,
              });
              context.load(highlightSearchResults, "items/font");
              await context.sync();
              if (highlightSearchResults.items.length === 0) continue;
              range = highlightSearchResults.items[0];
            }

            range.load("font");
            await context.sync();
            if (range.font.strikeThrough && isRedline) {
              console.log(`Skipping already struck-through text: "${result.highlightText}"`);
              continue;
            }

            rangesToProcess.push(range);
          }

          if (rangesToProcess.length === 0) {
            throw new Error(`No valid ranges found to apply for text: "${result.highlightText}".`);
          }

          for (let index = 0; index < rangesToProcess.length; index++) {
            const range = rangesToProcess[index];
            range.font.strikeThrough = true;
            range.font.color = "#C62828";
            const spaceRange = range.insertText(" ", "After");
            const newRange = spaceRange.insertText(result.suggestion, "After");
            newRange.font.bold = true;
            newRange.font.color = "#2E7D32";
            newRange.font.underline = "Single";
            newRange.font.highlightColor = null;

            const contentControlTag = `clause_${appliedCount + 1}_${result.uniqueId}_${Date.now()}`;
            const { data, error } = await StoreClause({
              clause_text: result.suggestion,
              source_type: "playbook",
              reason: result.reason,
              rule_id: result.ruleId,
              user_id: (await supabase.auth.getUser()).data.user?.id || "",
              anchor_tag_id: contentControlTag,
            });

            if (error) {
              throw new Error(`Failed to save clause: ${error.message}`);
            }

            if (!data?.clauseInstanceId) {
              throw new Error("Clause saved but no clauseInstanceId returned.");
            }

            const contentControl = newRange.insertContentControl();
            contentControl.tag = contentControlTag;
            contentControl.title = `Clause ${data.clauseInstanceId}`;
            contentControl.cannotEdit = true;
            contentControl.appearance = Word.ContentControlAppearance.hidden;

            const { error: anchorError } = await UpdateClauseAnchor(data.clauseInstanceId, contentControlTag);
            if (anchorError) {
              throw new Error(`Failed to update anchor tag for clause ID ${data.clauseInstanceId}: ${anchorError.message}`);
            }

            appliedClauseInstanceIds.push(data.clauseInstanceId);
            appliedContentControlTags.push(contentControlTag);
            appliedCount++;

            await context.sync();
          }
        }

        if (appliedCount > 0) {
          setResults((prev) => {
            let updatedResults = prev.map((r) =>
              r.uniqueId === result.uniqueId
                ? {
                    ...r,
                    status: "applied" as "applied", // Explicitly cast to the correct type
                    clauseInstanceId: appliedClauseInstanceIds[0] || null,
                    contentControlTag: appliedContentControlTags[0] || null,
                    isLoading: false,
                  }
                : r
            );
            // If this is an "Apply All" action, hide all other results except this grouped result
            if (result.ruleName.endsWith("(All)")) {
              console.log("Hiding all other results for Apply All, keeping uniqueId:", result.uniqueId);
              updatedResults = updatedResults.filter(
                (r) => r.uniqueId === result.uniqueId
              );
            }
            return updatedResults;
          });

          setClauseInstanceIds((prev) => [...prev, ...appliedClauseInstanceIds]);

          setNotification({
            open: true,
            message:
              appliedCount > 1
                ? `Successfully applied ${appliedCount} instance(s) and saved ${appliedClauseInstanceIds.length} clause(s) to database. First ID: ${appliedClauseInstanceIds[0] || "N/A"}`
                : `Successfully applied "${result.highlightText}" to "${result.suggestion}" and saved clause to database. ID: ${appliedClauseInstanceIds[0] || "N/A"}`,
            severity: "success",
          });
        } else {
          throw new Error(`No changes applied for text: "${result.highlightText}".`);
        }
      });
    } catch (e: any) {
      console.error("Apply failed:", e);
      setResults((prev) =>
        prev.map((r) =>
          r.uniqueId === result.uniqueId ? { ...r, isLoading: false } : r
        )
      );
      setNotification({
        open: true,
        message: `Failed to apply changes: ${e.message || "An unknown error occurred."}`,
        severity: "error",
      });
    }
  };

  const handleViewChange = async (result: IAnalysisResult): Promise<void> => {
    try {
      if (!result.clauseInstanceId || !result.contentControlTag) {
        console.error("Missing clauseInstanceId or contentControlTag for View Change:", result);
        setNotification({
          open: true,
          message: "No clause instance ID or content control tag available for this change.",
          severity: "error",
        });
        return;
      }

      console.log(`Attempting to navigate to clauseInstanceId: ${result.clauseInstanceId} with tag: ${result.contentControlTag}`);
      await Word.run(async (context) => {
        const contentControls = context.document.contentControls.getByTag(result.contentControlTag);
        context.load(contentControls, "items");
        await context.sync();

        console.log(`Found ${contentControls.items.length} content controls with tag: ${result.contentControlTag}`);

        if (contentControls.items.length > 0) {
          const contentControl = contentControls.items[0];
          contentControl.select();
          const range = contentControl.getRange();
          range.load("font");
          await context.sync();
          range.font.highlightColor = "#FFFF00";
          await context.sync();
          setTimeout(async () => {
            await Word.run(async (context) => {
              range.load("font");
              await context.sync();
              range.font.highlightColor = null;
              await context.sync();
            });
          }, 1000);
          setNotification({
            open: true,
            message: `Navigated to clause ID: ${result.clauseInstanceId}`,
            severity: "success",
          });
        } else {
          console.warn(`No content control found for tag: ${result.contentControlTag}. Attempting fallback text search.`);
          const range = await findTextRange(context, result);
          if (range) {
            range.select();
            range.load("font");
            await context.sync();
            range.font.highlightColor = "#FFFF00";
            await context.sync();
            setTimeout(async () => {
              await Word.run(async (context) => {
                range.load("font");
                await context.sync();
                range.font.highlightColor = null;
                await context.sync();
              });
            }, 1000);
            setNotification({
              open: true,
              message: `Navigated to text for clause ID: ${result.clauseInstanceId} (content control not found).`,
              severity: "success",
            });
          } else {
            console.error(`No content control or text found for clause ID: ${result.clauseInstanceId}`);
            setNotification({
              open: true,
              message: `Could not navigate to clause ID: ${result.clauseInstanceId}. Content control or text not found.`,
              severity: "error",
            });
          }
        }
      });
    } catch (error) {
      console.error("Error in handleViewChange:", error);
      setNotification({
        open: true,
        message: `Navigation failed: ${error instanceof Error ? error.message : "Unknown error"}`,
        severity: "error",
      });
    }
  };

  const handleIgnore = async (result: IAnalysisResult): Promise<void> => {
    try {
      await Word.run(async (context) => {
        const targetRange = await findTextRange(context, result);
        if (targetRange) {
          targetRange.load("font");
          await context.sync();
          targetRange.font.highlightColor = null;
          await context.sync();
        }
      });
      setResults((prev) =>
        prev.map((r) => (r.uniqueId === result.uniqueId ? { ...r, status: "ignored" } : r))
      );
      setNotification({
        open: true,
        message: "Suggestion ignored successfully!",
        severity: "success",
      });
    } catch (e: any) {
      console.error("Could not remove highlight for ignored item:", e);
      setNotification({
        open: true,
        message: `Failed to ignore suggestion: ${e.message || "Unknown error"}`,
        severity: "error",
      });
    }
  };

  const handleDeleteRule = async (result: IAnalysisResult): Promise<void> => {
    try {
      setNotification({ open: true, message: "Rule deleted successfully!", severity: "success" });
      setResults((prev) => prev.filter((r) => r.uniqueId !== result.uniqueId));
    } catch (e: any) {
      console.error("Could not delete rule:", e);
      setNotification({
        open: true,
        message: `Failed to delete rule: ${e.message || "Unknown error"}`,
        severity: "error",
      });
    }
  };

  const openEditDialog = (result: IAnalysisResult) => {
    setCurrentResultForEdit(result);
    setEditedSuggestion(result.suggestion);
    setEditedRuleName(result.ruleName);
    setEditedInstruction(result.instruction);
    setEditedResponseType(result.responseType as "Redline" | "Suggestion" | "Draft");
    setEditDialogOpen(true);
  };

  const handleEditSave = async () => {
    if (currentResultForEdit) {
      const updatedResult = {
        ...currentResultForEdit,
        ruleName: editedRuleName,
        suggestion: editedSuggestion,
        instruction: editedInstruction,
        responseType: editedResponseType,
        ruleId: currentResultForEdit.ruleId,
      };
      await handleApply(updatedResult);
    }
    setEditDialogOpen(false);
    setCurrentResultForEdit(null);
  };

  const handleCloseNotification = (_event?: React.SyntheticEvent | Event, reason?: string) => {
    if (reason === "clickaway") {
      return;
    }
    setNotification(null);
  };

  return (
    <GlassmorphicCard>
      {notification && (
        <Snackbar
          open={notification.open}
          autoHideDuration={6000}
          onClose={handleCloseNotification}
          anchorOrigin={{ vertical: "top", horizontal: "center" }}
        >
          <Alert
            onClose={handleCloseNotification}
            severity={notification.severity}
            sx={{ width: "100%" }}
          >
            <AlertTitle>{notification.severity === "success" ? "Success" : "Error"}</AlertTitle>
            {notification.message}
          </Alert>
        </Snackbar>
      )}
      {playbookToRun && (
        <Alert severity="info" sx={{ mb: 2, bgcolor: "rgba(3, 169, 244, 0.2)", color: "#fff" }}>
          Running analysis with Playbook: <strong>{playbookToRun.name}</strong>
        </Alert>
      )}
      <Typography variant="h5" gutterBottom sx={{ fontWeight: "bold", color: "#fff" }}>
        Compliance Analysis
      </Typography>
      <Paper
        elevation={0}
        sx={{
          p: 1.5,
          width: "100%",
          background:
            "linear-gradient(135deg, rgba(42, 45, 58, 0.8) 0%, rgba(30, 32, 42, 0.8) 100%)",
          borderRadius: "12px",
          border: "1px solid rgba(255, 255, 255, 0.1)",
          backdropFilter: "blur(5px)",
          mb: 2,
        }}
      >
        <Grid container alignItems="center" textAlign="center">
          <Box sx={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}>
            <Typography variant="h6" sx={{ fontWeight: "bold", color: "#4caf50" }}>
              {results.filter((r) => r.isCompliant || r.status === "applied").length}
            </Typography>
            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              <CheckCircle sx={{ fontSize: "1rem", color: "#4caf50" }} />
              <Typography variant="caption" sx={{ color: "rgba(255, 255, 255, 0.7)" }}>
                ✔ Compliant
              </Typography>
            </Box>
          </Box>
          <Box sx={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}>
            <Stack alignItems="center" spacing={0.5}>
              <Typography variant="h6" sx={{ fontWeight: "bold", color: "#f44336" }}>
                {results.filter((r) => !r.isCompliant && r.status === "pending").length}
              </Typography>
              <Stack direction="row" alignItems="center" spacing={0.5}>
                <Cancel sx={{ fontSize: "1rem", color: "#f44336" }} />
                <Typography variant="body2" sx={{ color: "rgba(255, 255, 255, 0.7)" }}>
                  ❌ Issues
                </Typography>
              </Stack>
            </Stack>
          </Box>
        </Grid>
      </Paper>

      <Card sx={{ background: SECONDARY_GRADIENT, p: 2, mb: 2, color: "white" }}>
        <Typography variant="subtitle1" gutterBottom>
          Add Context (Optional)
        </Typography>
        <FormControl variant="standard" fullWidth sx={{ mb: 2 }}>
          <InputLabel sx={{ color: "rgba(255,255,255,0.7)" }}>Writing Type</InputLabel>
          <Select
            value={contractType}
            onChange={(e) => setContractType(e.target.value)}
            sx={{ color: "white", "& .MuiSvgIcon-root": { color: "white" } }}
          >
            <MenuItem value="">
              <em>None</em>
            </MenuItem>
            <MenuItem value="Legal Agreement">Legal Agreement</MenuItem>
            <MenuItem value="Business Email">Business Email</MenuItem>
            <MenuItem value="Technical Document">Technical Document</MenuItem>
            <MenuItem value="Marketing Copy">Marketing Copy</MenuItem>
          </Select>
        </FormControl>
        <TextField
          label="Voice or Perspective"
          variant="standard"
          fullWidth
          value={partyRole}
          onChange={(e) => setPartyRole(e.target.value)}
          sx={{ mb: 2, input: { color: "white" }, label: { color: "rgba(255,255,255,0.7)" } }}
        />
        <TextField
          label="Specific Concerns (e.g., risk, clarity)"
          variant="standard"
          fullWidth
          value={concerns}
          onChange={(e) => setConcerns(e.target.value)}
          sx={{ input: { color: "white" }, label: { color: "rgba(255,255,255,0.7)" } }}
        />
      </Card>
      <GradientButton
        fullWidth
        startIcon={isLoading ? <CircularProgress size={20} color="inherit" /> : <Science />}
        onClick={() => handleStart()}
        disabled={isLoading}
      >
        {isLoading ? "Analyzing..." : "Start Analysis"}
      </GradientButton>

      <Box sx={{ mt: 3, maxHeight: "60vh", overflowY: "auto", pr: 1, scrollbarWidth: "none" }}>
        {isLoading && results.length === 0 ? (
          <Box sx={{ display: "flex", justifyContent: "center", mt: 4 }}>
            <CircularProgress color="inherit" />
          </Box>
        ) : results.length === 0 ? (
          <Typography sx={{ color: "rgba(255,255,255,0.7)", textAlign: "center", mt: 2, px: 1 }}>
            {uiMessage}
          </Typography>
        ) : (
          <>
            {results
              .filter((r) => r.ruleName.endsWith("(All)"))
              .map((result) => (
                <Grow in={true} timeout={300} key={result.uniqueId}>
                  <Card
                    sx={{
                      background: "linear-gradient(45deg, #021e2cff, #072f42ff)",
                      color: "white",
                      mb: 2,
                      p: 2,
                      borderRadius: "12px",
                      boxShadow: "0 4px 20px rgba(130, 124, 124, 0.2)",
                    }}
                  >
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 1 }}>
                      <Typography variant="h6" sx={{ fontWeight: "bold", flexGrow: 1 }}>
                        {result.ruleName}
                      </Typography>
                      {result.status === "applied" ? (
                        <Chip
                          label="Applied"
                          size="small"
                          icon={<CheckCircle />}
                          sx={{
                            background: "linear-gradient(45deg, #3DDC84, #39D353)",
                            color: "#1A2E25",
                            fontWeight: "bold",
                          }}
                        />
                      ) : (
                        <Chip
                          label="All Instances"
                          size="small"
                          sx={{
                            background: "linear-gradient(45deg, #3DDC84, #39D353)",
                            color: "#1A2E25",
                            fontWeight: "bold",
                          }}
                        />
                      )}
                    </Box>
                    <Typography variant="body2">
                      <strong>Reason:</strong> {result.reason}
                    </Typography>
                    <Typography variant="body2">
                      <strong>Suggestion:</strong> <RedlineText>{result.suggestion}</RedlineText>
                    </Typography>
                    {result.highlightText && (
                      <Typography variant="body2">
                        <strong>Highlight:</strong>{" "}
                        <span style={{ opacity: 0.8 }}>{result.highlightText}</span>
                      </Typography>
                    )}
                    <Box
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        gap: 1,
                        mt: 2,
                      }}
                    >
                      {result.status === "pending" && (
                        <Button
                          size="small"
                          variant="outlined"
                          sx={{
                            color: "#a5d6a7",
                            borderColor: "#a5d6a7",
                            "&:hover": {
                              backgroundColor: "rgba(165, 214, 167, 0.1)",
                              borderColor: "#a5d6a7",
                            },
                          }}
                          onClick={async () => {
                            await clearAllHighlights();
                            await highlightResultsInDocument(result);
                            await handleApply(result);
                          }}
                          disabled={result.isLoading}
                          startIcon={result.isLoading ? <CircularProgress size={16} color="inherit" /> : null}
                        >
                          {result.isLoading ? "Applying..." : "Apply All"}
                        </Button>
                      )}
                      {result.status === "applied" && result.clauseInstanceId && (
                        <Button
                          size="small"
                          variant="outlined"
                          sx={{
                            color: "#ffca28",
                            borderColor: "#ffca28",
                            flexGrow: 1,
                            "&:hover": {
                              backgroundColor: "rgba(255, 202, 40, 0.1)",
                              borderColor: "#ffca28",
                            },
                          }}
                          onClick={() => handleViewChange(result)}
                        >
                          View Change
                        </Button>
                      )}
                    </Box>
                  </Card>
                </Grow>
              ))}
            {results
              .filter((r) => !r.ruleName.endsWith("(All)"))
              .map((result) => (
                <Grow in={true} timeout={300} key={result.uniqueId}>
                  <Accordion
                    sx={{
                      background: "rgba(0,0,0,0.2)",
                      color: "white",
                      mb: 1,
                      borderRadius: "8px !important",
                    }}
                    expanded={expandedResultId === result.uniqueId}
                    onChange={async (_, expanded) => {
                      await clearAllHighlights();
                      setExpandedResultId(expanded ? result.uniqueId : null);
                      if (expanded) {
                        await highlightResultsInDocument(result);
                      }
                    }}
                  >
                    <AccordionSummary expandIcon={<ExpandMore sx={{ color: "white" }} />}>
                      <Box sx={{ display: "flex", alignItems: "center", width: "100%", gap: 1 }}>
                        <Typography sx={{ fontWeight: 600, flexGrow: 1 }}>
                          {result.ruleName}
                        </Typography>
                        {result.status === "pending" ? (
                          result.isCompliant ? (
                            <CheckCircleIcon sx={{ color: "#81c784", fontSize: 18 }} />
                          ) : (
                            <Cancel sx={{ color: "#e57373", fontSize: 18 }} />
                          )
                        ) : (
                          <Chip
                            label={result.status === "applied" ? "Applied" : "Ignored"}
                            icon={<CheckCircle />}
                            size="small"
                            sx={{
                              width: "fit-content",
                              fontWeight: "bold",
                              background:
                                result.status === "applied"
                                  ? "linear-gradient(45deg, #3DDC84, #39D353)"
                                  : "linear-gradient(45deg, #f44336, #d32f2f)",
                              color: "#1A2E25",
                              pointerEvents: "none",
                            }}
                          />
                        )}
                      </Box>
                    </AccordionSummary>
                    <AccordionDetails
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        gap: 1.5,
                        background: "rgba(0,0,0,0.15)",
                        p: 2,
                      }}
                    >
                      <Typography variant="body2">
                        <strong>Rule Name:</strong> {result.ruleName}
                      </Typography>
                      <Typography variant="body2">
                        <strong>Rule Type:</strong> {result.responseType}
                      </Typography>
                      <Typography variant="body2">
                        <strong>Instruction:</strong> {result.instruction}
                      </Typography>
                      <Typography variant="body2">
                        <strong>Status:</strong>{" "}
                        {result.isCompliant ? "Compliant" : "Non-Compliant"}
                      </Typography>
                      <Typography variant="body2">
                        <strong>Reason:</strong> {result.reason}
                      </Typography>
                      <Typography variant="body2">
                        <strong>Suggestion:</strong> <RedlineText>{result.suggestion}</RedlineText>
                      </Typography>
                      {result.highlightText && (
                        <Typography variant="body2">
                          <strong>Highlight:</strong>{" "}
                          <span style={{ opacity: 0.8 }}>{result.highlightText}</span>
                        </Typography>
                      )}
                      <Box
                        sx={{
                          display: "flex",
                          gap: 1,
                          mt: 1,
                          flexWrap: "wrap",
                          justifyContent: {
                            xs: "space-between",
                            sm: "flex-end",
                          },
                          "& button": {
                            flexGrow: {
                              xs: 1,
                              sm: 0,
                            },
                          },
                        }}
                      >
                        {result.status === "pending" && !result.isCompliant && (
                          <>
                            <Button
                              size="small"
                              variant="outlined"
                              sx={{ color: "#a5d6a7", borderColor: "#a5d6a7" }}
                              onClick={() => handleApply(result)}
                              disabled={result.isLoading}
                              startIcon={result.isLoading ? <CircularProgress size={16} color="inherit" /> : null}
                            >
                              {result.isLoading ? "Applying..." : "Apply"}
                            </Button>
                            <Button
                              size="small"
                              variant="outlined"
                              sx={{ color: "#ef9a9a", borderColor: "#ef9a9a" }}
                              onClick={() => handleIgnore(result)}
                            >
                              Ignore
                            </Button>
                            <Button
                              size="small"
                              variant="outlined"
                              sx={{ color: "#90caf9", borderColor: "#90caf9" }}
                              onClick={() => openEditDialog(result)}
                            >
                              Edit
                            </Button>
                            <Button
                              size="small"
                              variant="outlined"
                              sx={{ color: "#f44336", borderColor: "#f44336" }}
                              onClick={() => handleDeleteRule(result)}
                            >
                              Delete
                            </Button>
                          </>
                        )}
                        {result.status === "applied" && result.clauseInstanceId && (
                          <Button
                            size="small"
                            variant="outlined"
                            sx={{
                              color: "#ffca28",
                              borderColor: "#ffca28",
                              "&:hover": {
                                backgroundColor: "rgba(255, 202, 40, 0.1)",
                                borderColor: "#ffca28",
                              },
                            }}
                            onClick={() => handleViewChange(result)}
                          >
                            View Change
                          </Button>
                        )}
                      </Box>
                    </AccordionDetails>
                  </Accordion>
                </Grow>
              ))}
          </>
        )}
      </Box>

      <Dialog
        open={editDialogOpen}
        onClose={() => setEditDialogOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Edit Rule</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            margin="dense"
            label="Rule Name"
            value={editedRuleName}
            onChange={(e) => setEditedRuleName(e.target.value)}
          />
          <FormControl variant="filled" fullWidth sx={{ mt: 2 }}>
            <InputLabel>Rule Type</InputLabel>
            <Select
              value={editedResponseType}
              onChange={(e) =>
                setEditedResponseType(e.target.value as "Redline" | "Suggestion" | "Draft")
              }
            >
              <MenuItem value="Redline">Redline</MenuItem>
              <MenuItem value="Suggestion">Suggestion</MenuItem>
              <MenuItem value="Draft">Draft</MenuItem>
            </Select>
          </FormControl>
          <TextField
            fullWidth
            multiline
            rows={2}
            margin="dense"
            label="Instruction"
            value={editedInstruction}
            onChange={(e) => setEditedInstruction(e.target.value)}
            sx={{ mt: 2 }}
          />
          <TextField
            autoFocus
            fullWidth
            multiline
            rows={4}
            margin="dense"
            label="Suggested Text"
            value={editedSuggestion}
            onChange={(e) => setEditedSuggestion(e.target.value)}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleEditSave}>
            Save and Apply
          </Button>
        </DialogActions>
      </Dialog>
    </GlassmorphicCard>
  );
};

export default AnalysisTab;