
import { supabase } from './supabaseClient';

export const fetch_standard_Playbooks = async () => {
  // 1. Logged-in user ka data hasil karein
  const { data: { user }, error: userError } = await supabase.auth.getUser();

  if (userError || !user) {
    console.error('User not logged in:', userError?.message);
    // Agar user logged in nahi hai to sirf standard playbooks fetch karein
    const { data: standardOnly, error: standardError } = await supabase
      .from('playbooks')
      .select('*')
      .eq('readonly', true);
    
    return { 
      standardPlaybooks: standardOnly || [], 
      customPlaybooks: [],
      error: standardError
    };
  }

  // 2. Dono (standard aur custom) playbooks ek saath fetch karein
  const { data, error } = await supabase
    .from('Standard_paybooks')
    .select('*')
    .or(`readonly.eq.true,user_id.eq.${user.id}`); // Ya to readonly ho YA user_id match kare

  if (error) {
    console.error('Error fetching playbooks:', error.message);
    return { standardPlaybooks: [], customPlaybooks: [], error };
  }

  // 3. Data ko standard aur custom mein alag karein
  const standardPlaybooks = data.filter(pb => pb.readonly === true);
//   const customPlaybooks = data.filter(pb => pb.readonly === false);

  return { standardPlaybooks,  error: null };
};