
import { supabase } from "./supabaseClient";

/**
 * Naya custom playbook create karta hai.
 */
export const createPlaybook = async (playbookData) => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return { data: null, error: new Error("User not authenticated.") };

  const { data, error } = await supabase
    .from('playbooks')
    .insert({
      ...playbookData,
      user_id: user.id,
      readonly: false, // Custom playbooks hamesha editable hote hain
    })
    .select()
    .single();

  return { data, error };
};

/**
 * Maujooda playbook ko update karta hai.
 */
export const updatePlaybook = async (playbook) => {
  const { data, error } = await supabase
    .from('playbooks')
    .update({
      name: playbook.name,
      description: playbook.description,
      rules: playbook.rules,
    })
    .eq('id', playbook.id)
    .select()
    .single();

  return { data, error };
};

/**
 * Playbook ko uski ID se delete karta hai.
 */
export const deletePlaybook = async (playbookId) => {
  const { error } = await supabase
    .from('playbooks')
    .delete()
    .eq('id', playbookId);

  return { data: null, error };
};




